use crate::workspace::repo_root;
use anyhow::{Context, Result, bail};
use serde_json::Value;
use std::collections::{BTreeMap, BTreeSet};
use std::path::Path;
use std::process::Command;

pub const LICENSES_FILE: &str = "THIRD-PARTY-LICENSES.md";

pub const CRATES_HEADING: &str = "## Rust crates inside the binary";

pub const DRIVER_HEADING: &str = "## Packages inside the vendored browser driver";

const CRATES_INTRO: &str =
    "Each line below is a Rust crate that the imp binary compiles in. This list is generated by
`cargo xtask licenses` from the dependency graph of the CLI. Each line gives a crate, its license,
and its copyright lines. imp reads those lines from the license files of the crate, and falls back
to the authors of the crate. Where a crate offers a choice of licenses, imp uses it under one of
them. The text of each license is above.";

const DRIVER_INTRO: &str =
    "The vendored browser driver contains the npm packages below. This list is generated by
`cargo xtask vendor-puppeteer` when it bundles the driver. Each line gives a package, its license,
and its copyright lines. The text of each license is above.";

fn is_license_file(name: &str) -> bool {
    let upper = name.to_ascii_uppercase();
    upper.starts_with("LICENSE") || upper.starts_with("LICENCE") || upper.starts_with("COPYING")
}

pub fn copyright_lines(text: &str) -> Vec<String> {
    let mut lines = Vec::new();
    for line in text.lines() {
        let trimmed = line.trim().trim_start_matches(['/', '*', '#', ' ']).trim();
        let lower = trimmed.to_lowercase();
        let dated = |rest: &str| {
            rest.trim_start()
                .starts_with(|char: char| char.is_ascii_digit())
        };
        let is_notice = lower.starts_with("copyright ")
            || lower.strip_prefix("(c)").is_some_and(dated)
            || trimmed.strip_prefix('\u{a9}').is_some_and(dated);
        let is_template = lower.contains("[yyyy]")
            || lower.contains("{yyyy}")
            || lower.contains("<year>")
            || lower.contains("[year]")
            || lower.starts_with("copyright notice")
            || lower.starts_with("copyright and license")
            || lower.starts_with("copyright holder")
            || lower.starts_with("copyright owner")
            || lower.starts_with("copyright license")
            || lower.starts_with("copyright statement");
        if is_notice && !is_template && !lines.contains(&trimmed.to_string()) {
            lines.push(trimmed.to_string());
        }
    }
    lines
}

fn crate_copyright(directory: &Path, authors: &[String]) -> Vec<String> {
    let mut files: Vec<_> = std::fs::read_dir(directory)
        .into_iter()
        .flatten()
        .flatten()
        .filter(|entry| is_license_file(&entry.file_name().to_string_lossy()))
        .map(|entry| entry.path())
        .collect();
    files.sort();
    let mut lines = Vec::new();
    for file in files {
        let text = std::fs::read_to_string(&file).unwrap_or_default();
        for line in copyright_lines(&text) {
            if !lines.contains(&line) {
                lines.push(line);
            }
        }
    }
    if lines.is_empty() && !authors.is_empty() {
        lines.push(format!("authors: {}", authors.join(", ")));
    }
    lines
}

fn binary_crates() -> Result<Vec<String>> {
    let output = Command::new(std::env::var("CARGO").unwrap_or_else(|_| "cargo".into()))
        .args(["metadata", "--format-version", "1", "--locked"])
        .current_dir(repo_root())
        .output()
        .context("cannot run cargo metadata")?;
    if !output.status.success() {
        bail!(
            "cargo metadata failed: {}",
            String::from_utf8_lossy(&output.stderr)
        );
    }
    let metadata: Value = serde_json::from_slice(&output.stdout)?;
    let packages: BTreeMap<&str, &Value> = metadata["packages"]
        .as_array()
        .context("cargo metadata lists no packages")?
        .iter()
        .filter_map(|package| Some((package["id"].as_str()?, package)))
        .collect();
    let nodes: BTreeMap<&str, &Value> = metadata["resolve"]["nodes"]
        .as_array()
        .context("cargo metadata has no resolve graph")?
        .iter()
        .filter_map(|node| Some((node["id"].as_str()?, node)))
        .collect();
    let root = packages
        .values()
        .find(|package| package["name"] == "imp")
        .and_then(|package| package["id"].as_str())
        .context("cargo metadata has no imp package")?;
    let mut reached = BTreeSet::new();
    let mut pending = vec![root];
    while let Some(id) = pending.pop() {
        if !reached.insert(id) {
            continue;
        }
        for dependency in nodes[id]["deps"].as_array().into_iter().flatten() {
            let normal = dependency["dep_kinds"]
                .as_array()
                .into_iter()
                .flatten()
                .any(|kind| kind["kind"].is_null());
            if normal && let Some(target) = dependency["pkg"].as_str() {
                pending.push(target);
            }
        }
    }
    reached.remove(root);
    let mut lines: Vec<String> = reached
        .into_iter()
        .map(|id| {
            let package = packages[id];
            let directory = Path::new(package["manifest_path"].as_str().unwrap_or("."))
                .parent()
                .unwrap_or(Path::new("."))
                .to_path_buf();
            let authors: Vec<String> = package["authors"]
                .as_array()
                .into_iter()
                .flatten()
                .filter_map(|author| author.as_str().map(str::to_string))
                .collect();
            let mut parts = vec![
                format!(
                    "{}@{}",
                    package["name"].as_str().unwrap_or(""),
                    package["version"].as_str().unwrap_or("")
                ),
                package["license"].as_str().unwrap_or("unknown").to_string(),
            ];
            parts.extend(crate_copyright(&directory, &authors));
            parts.join(" - ")
        })
        .collect();
    lines.sort();
    Ok(lines)
}

fn section(heading: &str, intro: &str, lines: &[String]) -> String {
    format!("{heading}\n\n{intro}\n\n```\n{}\n```\n", lines.join("\n"))
}

pub fn replace_section(text: &str, heading: &str, body: &str) -> String {
    let Some(start) = text.find(&format!("\n{heading}\n")) else {
        return format!("{}\n\n---\n\n{body}", text.trim_end());
    };
    let start = start + 1;
    let rest = &text[start + heading.len()..];
    let end = rest
        .find("\n## ")
        .map(|offset| start + heading.len() + offset + 1)
        .unwrap_or(text.len());
    let tail = &text[end..];
    if tail.is_empty() {
        format!("{}{body}", &text[..start])
    } else {
        format!("{}{body}\n{tail}", &text[..start])
    }
}

pub fn driver_section(lines: &[String]) -> String {
    section(DRIVER_HEADING, DRIVER_INTRO, lines)
}

fn expected_text() -> Result<(String, String)> {
    let path = repo_root().join(LICENSES_FILE);
    let current = std::fs::read_to_string(&path)?;
    let expected = replace_section(
        &current,
        CRATES_HEADING,
        &section(CRATES_HEADING, CRATES_INTRO, &binary_crates()?),
    );
    Ok((current, expected))
}

fn check_coverage(text: &str) -> Result<()> {
    let uncovered = uncovered_licenses(text);
    if !uncovered.is_empty() {
        bail!(
            "{LICENSES_FILE} has no license text for:\n  {}\nadd the text of the license family by hand",
            uncovered.join("\n  ")
        );
    }
    Ok(())
}

pub fn write() -> Result<()> {
    let (current, expected) = expected_text()?;
    check_coverage(&expected)?;
    if current != expected {
        std::fs::write(repo_root().join(LICENSES_FILE), expected)?;
        println!("updated {LICENSES_FILE}");
    } else {
        println!("{LICENSES_FILE} is current");
    }
    Ok(())
}

pub fn verify() -> Result<()> {
    let (current, expected) = expected_text()?;
    check_coverage(&expected)?;
    if current != expected {
        bail!("{LICENSES_FILE} does not list the crates of the binary - run cargo xtask licenses");
    }
    Ok(())
}

const COVERED_LICENSES: &[&str] = &[
    "MIT",
    "Apache-2.0",
    "ISC",
    "BSD-2-Clause",
    "BSD-3-Clause",
    "0BSD",
    "MPL-2.0",
    "Unicode-3.0",
    "Zlib",
    "BSL-1.0",
    "CDLA-Permissive-2.0",
    "CC0-1.0",
];

fn spdx_tokens(expression: &str) -> Vec<String> {
    expression
        .replace('(', " ( ")
        .replace(')', " ) ")
        .replace('/', " OR ")
        .split_whitespace()
        .map(str::to_string)
        .collect()
}

fn covered_alternative(tokens: &[String], position: &mut usize) -> bool {
    let mut covered = covered_term(tokens, position);
    while tokens.get(*position).is_some_and(|token| token == "OR") {
        *position += 1;
        covered |= covered_term(tokens, position);
    }
    covered
}

fn covered_term(tokens: &[String], position: &mut usize) -> bool {
    let mut covered = covered_factor(tokens, position);
    while tokens.get(*position).is_some_and(|token| token == "AND") {
        *position += 1;
        covered &= covered_factor(tokens, position);
    }
    covered
}

fn covered_factor(tokens: &[String], position: &mut usize) -> bool {
    let Some(token) = tokens.get(*position) else {
        return false;
    };
    *position += 1;
    let covered = if token == "(" {
        let inner = covered_alternative(tokens, position);
        if tokens.get(*position).is_some_and(|token| token == ")") {
            *position += 1;
        }
        inner
    } else {
        COVERED_LICENSES.contains(&token.trim_end_matches('+'))
    };
    if tokens.get(*position).is_some_and(|token| token == "WITH") {
        *position += 2;
    }
    covered
}

pub fn uncovered_licenses(text: &str) -> Vec<String> {
    let mut uncovered = Vec::new();
    for line in text.lines() {
        let mut parts = line.split(" - ");
        let (Some(package), Some(expression)) = (parts.next(), parts.next()) else {
            continue;
        };
        if !package.contains('@') || package.contains(' ') {
            continue;
        }
        let tokens = spdx_tokens(expression);
        if !covered_alternative(&tokens, &mut 0) {
            uncovered.push(format!("{package} - {expression}"));
        }
    }
    uncovered
}
